import React, { useState, useEffect, useRef } from 'react';
import { LOGIN_URL, PROFILE_URL } from '../config';
import styled from 'styled-components';
import Alert from 'react-bootstrap/Alert';
import { MenuItem, Select, FormControl, InputLabel } from '@mui/material';
import { useLocation } from './AreaContext';

const LoginPage = styled.div`
  display: flex;
  height: 100vh;
  overflow: auto;
  background-color: #111;
  @media (max-width: 800px) {
    flex-direction: column;
  }
`;

const ContentSection = styled.div`
  position: relative;
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  padding: 30px;
  background: linear-gradient(to right, #011328, #0e2c4f);
  color: white;
  z-index: 1;
  min-height: 100vh;
  overflow: hidden;

  @media (max-width: 800px) {
    width: 100%;
    flex: none;
    order: 1;
  }
`;

const ImageSection = styled.div`
  position: relative;
  flex: 1;
  background-color: black;
  height: 100%;
  user-select: none;
  overflow: hidden;

  @media (max-width: 800px) {
    display: block;
    width: 100%;
    flex: none;
    order: 2;
  }
`;

const Title = styled.h1`
  font-size: 2.2rem;
  margin-top: 20px;
  margin-bottom: 20px;
  text-align: center;
  color: #dfebeb;
  font-weight: 700;

  letter-spacing: 1px;
  text-shadow: 0 2px 4px rgba(0, 0, 0, 0.4);
`;

const LoginButton = styled.button`
  background-color: #176498;
  color: white;
  padding: 6px;
  border: none;
  font-size: 12pt;
  cursor: pointer;
  width: 100%;
  height: 40px;

  &:hover {
    background-color: #0056b3;
  }

  @media (max-width: 768px) {
    width: 100%;
    font-size: 1rem;
  }
`;

const DottedMap = styled.img`
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  max-width: 800px;
  opacity: 0.3;
  pointer-events: none;
  z-index: -1;
  left: 50%;
  transform: translateX(-50%);
`;

const Logo = styled.img`
  margin-top: 20px;
  margin-right: 20px;
  width: auto;
  height: 60px;
  display: inline;
`;

const LoadingContainer = styled.div`
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  height: 100vh;
  background-color: black;
  color: white;
`;

const LoadingText = styled.p`
  font-size: 1.0rem;
  margin-bottom: 20px;
`;

const LoadingGif = styled.img`
  width: 16px;
  height: 16px;
  margin-left: 10px;
`;

const ColorExplanation = styled.div`
  position: absolute;
  bottom: 30px;
  left: 50%;
  transform: translateX(-50%);
  color: white;
  font-size: 0.9rem;
  display: flex;
  justify-content: center;
  gap: 16px;
  z-index: 100;
  flex-wrap: no-wrap;
  text-align: center;
  width: 100%;
`;

const Login = () => {
  const [loginError, setLoginError] = useState(null);
  const [loading, setLoading] = useState(true);
  const { selectedLocation, setSelectedLocation } = useLocation();

  const [currentImage, setCurrentImage] = useState(0);
  const intervalRef = useRef(null);
  const images = ['images/login1.png', 'images/login3.png', 'images/login2.png', 'images/login4.jpg'];

  const startInterval = () => {
    intervalRef.current = setInterval(() => {
      setCurrentImage(prev => (prev + 1) % images.length);
    }, 8000); // 8s
  };

  useEffect(() => {
    startInterval();
    return () => clearInterval(intervalRef.current);
  }, []);

  useEffect(() => {
    const checkAuthentication = async () => {
      try {
        const response = await fetch(PROFILE_URL, {
          credentials: 'include',
        });

        if (response.ok) {
          setLoginError('')
          window.location.href = '/';
        } else {
          setLoading(false);
          setLoginError('')
        }
      } catch (error) {
        console.error('Error checking authentication:', error);
        setLoading(false);
        setLoginError('Login Failed. If problems persist, please contact your system administrator.')
      }
    };

    checkAuthentication();
  }, []);

  const handleLogin = () => {
    if (selectedLocation) {
      window.location.href = LOGIN_URL;
    } else {
      setLoginError('Please select area first.');
    }
  };  

  const handleDotClick = (idx) => {
    setCurrentImage(idx);
    clearInterval(intervalRef.current);
    startInterval();
  };

  if (loading) {
    return (
      <LoadingContainer>
        <LoadingText>
          Loading
          <LoadingGif src="images/ajax-loader.gif" alt="Loading" />
        </LoadingText>
      </LoadingContainer>
    );
  }

  return (
    <LoginPage>
      <ImageSection bgImage={'images/map.png'}>
        {images.map((img, index) => (
          <img
            key={index}
            src={img}
            alt={`Slide ${index + 1}`}
            style={{
              position: 'absolute',
              top: 0,
              left: 0,
              width: '100%',
              height: '100%',
              objectFit: 'cover',
              opacity: currentImage === index ? 0.7 : 0,
              transition: 'opacity 1s ease-in-out',
              zIndex: currentImage === index ? 1 : 0,
              pointerEvents: 'none',
            }}
          />
        ))}

        {currentImage === 0 && (
          <ColorExplanation>
            <p style={{ background: '#8c5473', padding: '2px 4px', fontSize: '10pt' }}>Under consideration</p> 
            <p style={{ background: '#c17c02', padding: '2px 4px', fontSize: '10pt' }}>Pre-operational</p> 
            <p style={{ background: '#2c6809', padding: '2px 4px', fontSize: '10pt' }}>Operational</p> 
          </ColorExplanation>
        )}

        {currentImage === 3 && (
          <ColorExplanation>
            <p className='slogan-text-2' style={{fontSize: '1rem'}}>
              Subdivision staff? Contact us to add your FIR.
            </p>
          </ColorExplanation>
        )}

        <div style={{ position: 'absolute', bottom: 10, left: '50%', transform: 'translateX(-50%)', display: 'flex', gap: 8 }}>
          {images.map((_, idx) => (
            <div
              key={idx}
              onClick={() => handleDotClick(idx)}
              style={{
                width: 11,
                height: 11,
                borderRadius: '50%',
                background: idx === currentImage ? '#fff' : '#484b4c',
                cursor: 'pointer',
                transition: 'background 0.3s',
                pointerEvents: 'all',
                zIndex: 999
              }}
            />
          ))}
        </div>
      </ImageSection>

      <ContentSection>
        <DottedMap className='login-map-2' src='images/map2.png'></DottedMap>

        <div style={{ display: 'inline', alignItems: 'center'}}>
          <Logo src="images/logo.svg" alt="VATSIM Scandinavia" />
          <Logo src='images/vlara-logo.svg' alt='V-LARA' style={{height: '36px', marginLeft: '10px'}}/>
        </div>

        <Title>LARA Web Booking Client</Title>

        <div style={{ display: 'flex', alignItems: 'center', width: '100%', marginBottom: '20px' }}>
          <FormControl style={{ marginRight: '10px', flex: 1 }}>
            <Select
              className='text-fields no-border-radius'
              id="area-select"
              value={selectedLocation}
              onChange={(e) => setSelectedLocation(e.target.value)}
              size="small"
            >
              <MenuItem value="efin" className='login-finland'>EFINZAMC | Finland</MenuItem>
              
              <MenuItem value="eett" style={{color: '#a1a1a1'}}>EETTZAMC | Estonia (not operational)</MenuItem>
              <MenuItem value="eacc" style={{color: '#a1a1a1'}}>EACCZAMC | Amswell (test environment)</MenuItem>
            </Select>
          </FormControl>
          <LoginButton onClick={handleLogin} style={{ flex: 1 }}>Login with VATSIM</LoginButton>
        </div>


        {loginError && <p style={{ color: 'red' }}>{loginError}</p>}

        <Alert key={'success'} variant={'success'} style={{width: '100%', borderRadius: '0'}}>
          <b>Local and sub-regional airspace management support system</b><br/>
          Create and manage airspace reservations on VATSIM network!
        </Alert>


        <p className='slogan-text-2'>Supporting VATSIM Aviation</p>

      </ContentSection>
    </LoginPage>
  );
};

export default Login;

